//! Replays `testdata/port/ingest/structured.json`, generated by the real Go
//! `TestPortIngestStructuredContract`: the Go XML decoder diagnostics surfaced
//! by the DOCX/XLSX/PPTX/ODF readers, EPUB/EML extraction, ZIP defence cases
//! and the regexp/html text helpers.
use base64::{Engine, engine::general_purpose::STANDARD};
use serde::Deserialize;
use symdesk_ingest::{extract, structured};

#[derive(Clone, Deserialize)]
struct Res {
    #[serde(rename = "Text")]
    text: String,
    #[serde(rename = "MIME")]
    mime: String,
    #[serde(rename = "Engine")]
    engine: String,
    #[serde(rename = "Language")]
    language: String,
}

#[derive(Clone, Deserialize)]
struct Case {
    id: String,
    group: String,
    reader: String,
    #[serde(default)]
    name: String,
    input: String,
    #[serde(default)]
    shared: Vec<String>,
    #[serde(default)]
    kind: String,
    #[serde(default)]
    detect: String,
    #[serde(default)]
    detect_error: String,
    #[serde(default)]
    text: String,
    result: Option<Res>,
    #[serde(default)]
    error: String,
    #[serde(default)]
    panic: String,
}

#[derive(Deserialize)]
struct Fixture {
    schema_version: u32,
    cases: Vec<Case>,
}

fn fixture() -> Fixture {
    serde_json::from_slice(
        &std::fs::read(
            std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../../testdata/port/ingest/structured.json"),
        )
        .unwrap(),
    )
    .unwrap()
}

/// Go reports a recovered panic; Rust returns an error instead of crashing.
fn expected_error(c: &Case) -> String {
    if c.panic.is_empty() {
        c.error.clone()
    } else {
        format!("extract: panic in Go reader: {}", c.panic)
    }
}

/// Declared difference: Go's flate reports the input byte offset of corrupt
/// deflate data (`flate: corrupt input before offset N`); the Rust inflate
/// (miniz_oxide) rejects the same data without an offset. The error class,
/// the rejection and the absence of output are identical.
fn flate_offset_equivalent(go: &str, rust: &str) -> bool {
    go.split_once("flate: corrupt input before offset ")
        .zip(rust.split_once("flate: corrupt input"))
        .is_some_and(|((go_prefix, offset), (rust_prefix, rest))| {
            go_prefix == rust_prefix && rest.is_empty() && offset.chars().all(|c| c.is_ascii_digit())
        })
}

fn run(c: &Case) -> Result<(), String> {
    let data = STANDARD.decode(&c.input).unwrap();
    match c.group.as_str() {
        "xml-direct" => {
            let got = match c.reader.as_str() {
                "word" => structured::word_xml_to_text(&data),
                "odf" => structured::odf_xml_to_text(&data),
                "pptx" => structured::pptx_xml_to_text(&data),
                "sheet" => structured::sheet_xml_to_text(&data, &c.shared),
                r => panic!("reader {r}"),
            };
            let want = if c.error.is_empty() && c.panic.is_empty() {
                Ok(c.text.clone())
            } else {
                Err(expected_error(c))
            };
            if got == want {
                Ok(())
            } else {
                Err(format!("{got:?} != {want:?}"))
            }
        }
        "html" => {
            let got = extract::html_to_text(&String::from_utf8_lossy(&data));
            if got == c.text {
                Ok(())
            } else {
                Err(format!("{got:?} != {:?}", c.text))
            }
        }
        "normalize" => {
            let got = extract::normalize_text(&String::from_utf8_lossy(&data));
            if got == c.text {
                Ok(())
            } else {
                Err(format!("{got:?} != {:?}", c.text))
            }
        }
        _ => {
            let detection = extract::detect_bytes(&c.name, &data);
            if c.detect_error.is_empty() {
                if detection != Ok(c.detect.clone()) {
                    return Err(format!("detect {detection:?} != {:?}", c.detect));
                }
            } else if detection.is_ok() {
                return Err(format!("detect {detection:?} != error {:?}", c.detect_error));
            }
            let got = extract::extract_bytes(&data, &c.kind, usize::MAX);
            let want = match (&c.result, expected_error(c)) {
                (_, e) if !e.is_empty() => Err(e),
                (Some(r), _) => Ok(extract::Extraction {
                    text: r.text.clone(),
                    mime: r.mime.clone(),
                    engine: r.engine.clone(),
                    language: r.language.clone(),
                }),
                (None, _) => panic!("case {} has neither result nor error", c.id),
            };
            if got == want {
                return Ok(());
            }
            if let (Err(g), Err(w)) = (&got, &want)
                && flate_offset_equivalent(w, g)
            {
                return Ok(());
            }
            Err(format!("{got:?} != {want:?}"))
        }
    }
}

#[test]
fn structured_go_fixture() {
    let f = fixture();
    assert_eq!(f.schema_version, 1);
    let mut failures = Vec::new();
    for c in &f.cases {
        if let Err(e) = run(c) {
            failures.push(format!("{} ({}): {}", c.id, c.group, e.chars().take(300).collect::<String>()));
        }
    }
    let mut by_group = std::collections::BTreeMap::new();
    for c in &f.cases {
        *by_group.entry(c.group.clone()).or_insert(0usize) += 1;
    }
    eprintln!("replayed {} cases {by_group:?}, {} failures", f.cases.len(), failures.len());
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.iter().take(40).cloned().collect::<Vec<_>>().join("\n")
    );
    assert_eq!(f.cases.len(), 2520);
}

#[test]
fn structured_negative_control() {
    let f = fixture();
    let mut c = f.cases.iter().find(|c| c.id == "docx-basic").unwrap().clone();
    assert!(run(&c).is_ok());
    c.result.as_mut().unwrap().text.push_str("tampered");
    assert!(run(&c).is_err());
}
